:root {
  color-scheme: dark;
  --rail-width: 430px;
  --nav-font: 22px;
  --row-rest: url('../assets/navigation/frame-430-72-rest.png');
  --row-current: url('../assets/navigation/frame-430-72-current.png');
  --rail-heading: url('../assets/navigation/frame-430-44-rest.png');
  --rail-home: url('../assets/navigation/frame-430-52-rest.png');
  font-family: Georgia, 'Times New Roman', serif;
  color: #ebede1;
}
* { box-sizing: border-box; }
html { min-height: 100%; background: #17223b; }
body { margin: 0; min-height: 100svh; }
button, a { -webkit-tap-highlight-color: transparent; }
button { font: inherit; color: inherit; cursor: pointer; }
a { color: inherit; }
button, a { touch-action: manipulation; }
.realm-background {
  position: fixed; inset: 0; z-index: -1;
  background: url('../outputs/the-haunted-realm-background-corrected-review-v3.png') center / cover no-repeat;
}
main { position: relative; }
.is-menu-open main { visibility: hidden; }
.visually-hidden {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0;
}
.skip-link { position: fixed; left: 16px; top: -70px; z-index: 30; padding: 12px; background: #25334a; }
.skip-link:focus { top: 8px; }
:focus-visible { outline: 2px solid #e0ba77; outline-offset: 3px; }
[hidden] { display: none !important; }
.global-navigation { position: relative; z-index: 10; }
.navigation-controls { position: fixed; top: 8px; left: 16px; right: 16px; display: flex; justify-content: space-between; pointer-events: none; }
.home-control, .activities-control {
  position: relative; display: flex; align-items: center; justify-content: center;
  width: 179px; height: 48px; text-decoration: none; border: 0; padding: 0;
  background: url('../assets/navigation/frame-179-48-rest.png') center / 100% 100% no-repeat;
  font-size: 18px; pointer-events: auto;
  text-shadow: -1px 0 #070b12, 1px 0 #070b12, 0 -1px #070b12, 0 1px #070b12;
}
.home-control[aria-current='page'] { color: #ffda8f; font-weight: bold; background-image: url('../assets/navigation/frame-179-48-current.png'); }
.chevron { width: 8px; height: 8px; border-right: 2px solid #e3e6df; border-bottom: 2px solid #e3e6df; transform: rotate(45deg); margin-left: 14px; margin-top: -4px; }
[aria-expanded='true'] .chevron { transform: rotate(225deg); margin-top: 4px; }
.activity-drawer { position: fixed; right: 16px; top: 64px; width: 430px; height: min(740px, calc(100svh - 80px)); }
.drawer-chains { position: absolute; inset: 10px 0; pointer-events: none; }
.drawer-chains::before, .drawer-chains::after {
  content: ''; position: absolute; top: 0; bottom: 0; width: 66px;
  background-position: center; background-size: 66px 100%; background-repeat: no-repeat;
}
.drawer-chains::before { left: 18px; background-image: url('../assets/navigation/chain-left.png'); }
.drawer-chains::after { right: 18px; background-image: url('../assets/navigation/chain-right.png'); }
.drawer-heading {
  position: relative; height: 44px; display: flex; align-items: center; justify-content: space-between; padding: 0 32px;
  background: var(--rail-heading) center / 100% 100% no-repeat;
  font-size: 20px; text-shadow: 0 1px 2px #070b12, 0 -1px 2px #070b12;
}
.close-drawer { border: 0; background: transparent; font-size: 16px; padding: 4px; text-shadow: 0 1px 2px #070b12; }
.rail-home { display: none; }
.destination-list {
  position: relative; display: flex; flex-direction: column; gap: 12px;
  height: calc(100% - 56px); margin: 8px 0 0; padding: 0 0 4px;
  overflow-y: auto; overflow-x: hidden; list-style: none;
  scrollbar-width: thin; scrollbar-color: #baa16d transparent; overscroll-behavior: contain;
  touch-action: pan-y;
}
.destination-list li { flex: 0 0 auto; }
.destination-link {
  display: flex; align-items: center; position: relative; height: 72px; width: 100%;
  padding: 0 29px 0 81px; text-decoration: none; font-size: var(--nav-font); line-height: 27px;
  background: var(--row-rest) center / 100% 100% no-repeat;
  text-shadow: -1px 0 #070b12, 1px 0 #070b12, 0 -1px #070b12, 0 1px #070b12;
}
.destination-link[aria-current='page'] { color: #ffda8f; font-weight: bold; background-image: var(--row-current); }
.destination-link:focus-visible { outline-offset: -4px; }
.destination-image { position: absolute; left: 28px; top: 17px; width: 38px; height: 38px; }
.destination-image img { display: block; width: 100%; height: 100%; }
.home-view .destination-link { height: 64px; background-image: url('../assets/navigation/frame-430-64-rest.png'); }
.home-view .destination-image { top: 13px; }
.activity-view .navigation-controls { display: none; }
.activity-view .activity-drawer { left: 16px; right: auto; top: 16px; width: var(--rail-width); height: calc(100svh - 32px); }
.activity-view .close-drawer { display: none; }
.activity-view .drawer-heading { justify-content: center; font-size: 24px; }
.activity-view .rail-home {
  display: flex; align-items: center; position: relative; height: 52px; margin-top: 12px; padding-left: 32px;
  text-decoration: none; font-size: 20px; background: var(--rail-home) center / 100% 100% no-repeat;
  text-shadow: 0 1px 2px #070b12, 0 -1px 2px #070b12;
}
.activity-view .destination-list { gap: 14px; margin-top: 44px; height: calc(100% - 152px); }
.home-title { padding-top: 65px; }
.home-title h1 { margin: 0; font-size: 0; }
.protected-title { display: block; width: 650px; height: 215px; margin: 0 auto; }
.home-destinations {
  max-width: 1480px; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 26px 24px; margin: 28px auto 0; padding: 0 22px 32px;
}
.scene-destination { display: block; min-width: 0; text-decoration: none; border: 0; background: transparent; }
.scene-destination:focus-visible { outline-offset: 4px; border-radius: 35%; }
.scene-space { display: flex; align-items: center; justify-content: center; height: 178px; }
.activity-scene { display: block; max-width: 100%; width: 420px; max-height: 178px; object-fit: contain; }
.scene-name { display: grid; margin: 0 auto; width: min(440px, 100%); }
.scene-name img { grid-area: 1 / 1; display: block; width: 100%; height: auto; }
.name-focus { opacity: 0; transition: opacity 180ms ease; }
.scene-destination:hover .name-focus, .scene-destination:focus-visible .name-focus { opacity: 1; }
.scene-destination:hover .name-rest, .scene-destination:focus-visible .name-rest { opacity: 0; }
.activity-main { padding: 100px 36px 36px calc(var(--rail-width) + 48px); min-height: 100svh; }
.activity-page-heading { margin-bottom: 30px; text-shadow: 0 2px 4px #11172a, 0 -1px 2px #11172a; }
.activity-page-heading h1 { margin: 6px 0 0; font-size: clamp(28px, 2.4vw, 42px); line-height: 1.25; overflow-wrap: break-word; }
.shell-status { margin: 0; font-size: 16px; letter-spacing: .06em; }
.content-space { min-height: max(360px, calc(100svh - 250px)); padding: 30px; border: 1px dashed rgba(192,209,222,.62); background: rgba(16,24,43,.18); text-shadow: 0 2px 3px #11172a; }
.content-space h2 { font-size: 24px; margin: 0 0 18px; }
.content-space p { font-size: 18px; line-height: 1.6; max-width: 620px; }
.noscript-note { padding: 80px 24px; }
@media (min-width: 1800px) {
  :root { --rail-width: 460px; --nav-font: 24px; --row-rest: url('../assets/navigation/frame-460-72-rest.png'); --row-current: url('../assets/navigation/frame-460-72-current.png'); --rail-heading: url('../assets/navigation/frame-460-44-rest.png'); --rail-home: url('../assets/navigation/frame-460-52-rest.png'); }
  .home-view .activity-drawer { width: 430px; --rail-heading: url('../assets/navigation/frame-430-44-rest.png'); }
  .home-view .destination-link { font-size: 22px; }
}
@media (max-width: 1100px) {
  .home-destinations { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 900px) {
  :root { --rail-width: 288px; --nav-font: 20px; --row-rest: url('../assets/navigation/frame-288-70-rest.png'); --row-current: url('../assets/navigation/frame-288-70-current.png'); --rail-heading: url('../assets/navigation/frame-288-44-rest.png'); }
  .navigation-controls, .activity-view .navigation-controls { display: flex; left: 8px; right: 8px; }
  .home-control { width: 136px; height: 52px; background-image: url('../assets/navigation/frame-136-52-rest.png'); }
  .home-control[aria-current='page'] { background-image: url('../assets/navigation/frame-136-52-current.png'); }
  .activities-control { width: 160px; height: 52px; background-image: url('../assets/navigation/frame-160-52-rest.png'); }
  .activity-drawer, .activity-view .activity-drawer {
    left: 16px; right: auto; top: 80px; width: 288px; height: calc(100svh - 106px);
    --rail-heading: url('../assets/navigation/frame-288-44-rest.png');
  }
  .drawer-heading, .activity-view .drawer-heading { font-size: 18px; justify-content: space-between; padding: 0 34px; }
  .close-drawer, .activity-view .close-drawer { display: block; font-size: 15px; }
  .activity-view .rail-home { display: none; }
  .destination-list, .activity-view .destination-list { gap: 8px; margin-top: 8px; height: calc(100% - 56px); }
  .destination-link, .home-view .destination-link { height: 70px; padding: 0 24px 0 68px; font-size: 20px; line-height: 25px; background-image: var(--row-rest); }
  .destination-image, .home-view .destination-image { left: 22px; top: 18px; width: 34px; height: 34px; }
  .activity-main { padding: 100px 24px 24px; }
  .content-space { padding: 24px; }
}
@media (max-width: 649px) {
  .protected-title { width: calc(100% - 32px); height: auto; }
  .home-destinations { grid-template-columns: minmax(0, 1fr); gap: 20px; padding: 0 16px 28px; }
  .scene-space { height: 168px; }
  .activity-scene { max-height: 168px; }
  .activity-main { padding-left: 16px; padding-right: 16px; }
  .content-space { padding: 20px; }
}
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none !important; scroll-behavior: auto !important; } }
